// Generated by a mechanical split of the original monolithic PaintSoftwareUITests
// class. Test bodies are unchanged; see PaintUITestCase for the shared helpers.

import XCTest

/// Keep the gallery-mutating tests in this one class. They are the only tests that pass
/// `-resetGallery` / `-simulateProjectCorruption` launch arguments, i.e. the only ones that
/// deliberately rewrite persistent project storage. XCTest runs a single class's tests serially on
/// one simulator clone, so grouping them here means they cannot race each other; splitting them
/// across classes would put them on separate clones, which is still safe today only because each
/// clone has its own container. Treat that as load-bearing rather than incidental — if you rebalance
/// these classes for runtime, move the fast tests around them, not these.
final class VectorShapeAndRecoveryUITests: PaintUITestCase {

    /// Creates a vector layer via the layer panel's add menu, draws a stroke on it, and verifies the
    /// stroke was recorded as *vector* geometry (not a raster stamp) and that it rendered to pixels.
    func testVectorLayerRecordsStrokeAsGeometryAndRenders() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        app.buttons["toolbar.layersButton"].tap()
        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addButton.press(forDuration: 1.2) // long-press opens the kind menu (a plain tap adds a raster layer)
        let vectorItem = app.buttons["Vector Layer"]
        XCTAssertTrue(vectorItem.waitForExistence(timeout: 5), "The add menu should offer a Vector Layer option")
        vectorItem.tap()

        // The new vector layer is on top (array index 1) and active.
        let marker = readVectorMarker(app, layerIndex: 1)
        XCTAssertEqual(marker?.isVector, true, "The newly added layer should be a vector layer")
        XCTAssertEqual(marker?.strokes, 0, "A fresh vector layer has no strokes yet")
        app.buttons["toolbar.layersButton"].tap() // close panel

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        drawLine(on: canvas, from: CGVector(dx: 0.3, dy: 0.5), to: CGVector(dx: 0.7, dy: 0.5))

        // The stroke should be stored as one vector stroke (geometry), and the raster tier untouched.
        app.buttons["toolbar.layersButton"].tap()
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.strokes, 1, "The stroke should be recorded as one vector stroke")
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 1), 0, "A vector-layer stroke must not land in the raster tier")
        app.buttons["toolbar.layersButton"].tap()

        // And it must actually render to pixels (black stroke on the mid-canvas line).
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)), "The vector stroke should be visible on the canvas")
    }

    /// Rasterize folds a vector layer's stroke into the raster tier (not a separate bakedImage layer)
    /// and flips its kind to raster — and the whole thing (content + kind) undoes as one step.
    func testRasterizeFoldsVectorLayerToBakedRasterAndUndoes() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        app.buttons["toolbar.layersButton"].tap()
        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addButton.press(forDuration: 1.2)
        let vectorItem = app.buttons["Vector Layer"]
        XCTAssertTrue(vectorItem.waitForExistence(timeout: 5))
        vectorItem.tap()
        app.buttons["toolbar.layersButton"].tap() // close panel

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        drawLine(on: canvas, from: CGVector(dx: 0.3, dy: 0.5), to: CGVector(dx: 0.7, dy: 0.5))

        app.buttons["toolbar.layersButton"].tap()
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.isVector, true, "Setup: should still be a vector layer")
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.strokes, 1, "Setup: the stroke should have landed as vector geometry")

        let row = app.staticTexts["layerPanel.row.1"]
        XCTAssertTrue(row.waitForExistence(timeout: 5))
        row.tap() // select
        row.tap() // open options
        let rasterize = app.buttons["layerOptions.rasterize"]
        XCTAssertTrue(rasterize.waitForExistence(timeout: 5), "A vector layer's options should offer Rasterize")
        rasterize.tap()

        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.isVector, false, "Rasterize should flip the layer to raster")
        XCTAssertEqual(readHasBakedImage(app, layerIndex: 1), false, "The stroke should be folded into the raster tier, not a separate baked-image tier")
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 1), 1, "The rasterized stroke should register as raster content")
        app.buttons["toolbar.layersButton"].tap() // close panel

        // Pixels should be unchanged by the conversion.
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)), "Rasterizing should not change what's on the canvas")

        let undo = app.buttons["sideToolbar.undoButton"]
        XCTAssertTrue(undo.waitForExistence(timeout: 5))
        XCTAssertTrue(undo.isEnabled, "Rasterize should be undoable")
        undo.tap()

        app.buttons["toolbar.layersButton"].tap()
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.isVector, true, "Undo should restore the vector layer in one step")
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.strokes, 1, "Undo should restore the vector stroke, not just the kind")
    }

    /// Exercises the custom palette builder end to end: sets a known color (blue) via the hex field
    /// on the Color tab, switches to the Palettes tab and taps "add current color" to append it to
    /// the seeded "Spectrum" preset, taps a different existing swatch to move the picker off blue,
    /// then taps the newly-added swatch and — back on the Color tab — confirms the hex field snapped
    /// back to blue. That round-trip proves both "add current color" and swatch selection actually
    /// drive the picker. Launches with `-resetPalettes` so Spectrum (20 swatches, indices 0–19) is
    /// present and the appended swatch lands at a known index (20).
    func testPaletteBuilderAddAndSelectSwatch() throws {
        let app = XCUIApplication()
        app.launchArguments.append("-resetPalettes")
        XCTAssertTrue(launchIntoEditor(app))

        let colorButton = app.buttons["toolbar.colorButton"]
        XCTAssertTrue(colorButton.waitForExistence(timeout: 5))
        colorButton.tap()

        // Set a known color (pure blue) via the hex field on the Color tab.
        let hexField = app.textFields["colorPanel.hexField"]
        XCTAssertTrue(hexField.waitForExistence(timeout: 5))
        setHexField(app, hexField, to: "0000FF")

        // Switch to the Palettes tab and append the current color. The seeded "Spectrum" preset has
        // 20 colors, so the new swatch lands at index 20.
        app.buttons["colorPanel.tab.palettes"].tap()

        let addButton = app.buttons["colorPanel.addSwatchButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addButton.tap()

        let addedSwatch = app.otherElements["colorPanel.swatch.20"]
        XCTAssertTrue(addedSwatch.waitForExistence(timeout: 5), "Adding the current color should append a swatch at index 20 of the Spectrum preset")

        // Move the picker to a different color by tapping an existing preset swatch (Spectrum[0] is
        // black), so re-selecting the added swatch is a real change.
        app.otherElements["colorPanel.swatch.0"].tap()

        // Tap the saved swatch; the picker should snap back to the stored blue.
        addedSwatch.tap()

        // Confirm on the Color tab that the hex field reflects the restored blue.
        app.buttons["colorPanel.tab.color"].tap()
        let hexAfterSelect = hexField.value as? String
        XCTAssertEqual(hexAfterSelect?.uppercased(), "0000FF", "Tapping the saved swatch should reload it into the picker, got \(String(describing: hexAfterSelect))")
    }

    /// The critical safety net: a project damaged by an update/crash must come back on its own.
    /// Saves a project, then relaunches with `-simulateProjectCorruption` — the app's launch hook
    /// overwrites the newest project's manifest.json with garbage and the normal startup
    /// maintenance pass then runs. Asserts the project is NOT left in the damaged state, is still
    /// listed normally, and still opens with the drawn stroke intact (i.e. it was auto-restored
    /// from its backup, not just hidden or deleted).
    func testCorruptedProjectIsAutoRestoredFromBackupOnLaunch() throws {
        let app = XCUIApplication()
        app.launchArguments = ["-resetGallery"]
        XCTAssertTrue(launchIntoEditor(app))

        dragOnCanvas(app, from: CGVector(dx: 0.3, dy: 0.3), to: CGVector(dx: 0.5, dy: 0.3))
        saveEditorAndReturnToGallery(app)

        app.terminate()
        app.launchArguments = ["-simulateProjectCorruption"]
        app.launch()

        // If auto-repair failed, the tile would read as damaged instead of opening.
        let damagedLabel = app.staticTexts["Damaged — tap to recover"]
        XCTAssertTrue(damagedLabel.waitForNonExistence(timeout: 10),
                      "Startup maintenance should auto-restore the damaged project from its backup")

        let restoredTile = app.staticTexts.matching(NSPredicate(format: "label == %@", "Untitled")).firstMatch
        XCTAssertTrue(restoredTile.waitForExistence(timeout: 10), "The restored project should be listed normally")
        restoredTile.tap()

        XCTAssertTrue(app.staticTexts["timeline.frameLabel"].waitForExistence(timeout: 10),
                      "The restored project should open in the editor (a still-damaged one would not)")
        openLayerPanel(app)
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 0), 1,
                       "The stroke saved before the corruption should survive the restore")
    }

    /// Deleting a project must never destroy it outright: it moves to Recently Deleted (Trash) and
    /// can be put back, with its content intact.
    func testDeletedProjectCanBeRestoredFromRecentlyDeleted() throws {
        let app = XCUIApplication()
        app.launchArguments = ["-resetGallery"]
        XCTAssertTrue(launchIntoEditor(app))

        dragOnCanvas(app, from: CGVector(dx: 0.3, dy: 0.3), to: CGVector(dx: 0.5, dy: 0.3))
        let tile = saveEditorAndReturnToGallery(app)

        // Delete via the tile's menu, confirming the alert.
        let menuButton = app.buttons["gallery.tileMenu.Untitled"]
        XCTAssertTrue(menuButton.waitForExistence(timeout: 5))
        menuButton.tap()
        let deleteItem = app.buttons["Delete"]
        XCTAssertTrue(deleteItem.waitForExistence(timeout: 5))
        deleteItem.tap()
        let confirmDelete = app.alerts.buttons["Delete"]
        XCTAssertTrue(confirmDelete.waitForExistence(timeout: 5))
        confirmDelete.tap()
        XCTAssertTrue(tile.waitForNonExistence(timeout: 5), "The deleted project should leave the gallery")

        // It must now be in Recently Deleted, from where it can be restored.
        let trashButton = app.buttons["gallery.recentlyDeletedButton"]
        XCTAssertTrue(trashButton.waitForExistence(timeout: 5))
        trashButton.tap()
        let restoreButton = app.buttons.matching(NSPredicate(format: "identifier BEGINSWITH %@", "gallery.trashRestore.")).firstMatch
        XCTAssertTrue(restoreButton.waitForExistence(timeout: 5), "Recently Deleted should list the deleted project")
        restoreButton.tap()

        let doneButton = app.buttons["Done"]
        XCTAssertTrue(doneButton.waitForExistence(timeout: 5))
        doneButton.tap()

        let restoredTile = app.staticTexts.matching(NSPredicate(format: "label == %@", "Untitled")).firstMatch
        XCTAssertTrue(restoredTile.waitForExistence(timeout: 5), "The restored project should reappear in the gallery")
        restoredTile.tap()
        XCTAssertTrue(app.staticTexts["timeline.frameLabel"].waitForExistence(timeout: 10),
                      "The restored project should open in the editor")
        openLayerPanel(app)
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 0), 1,
                       "The deleted project's stroke content should survive the trash/restore round trip")
    }

    /// The whole raster-layer path for the user-visible feature: hold a drawn line until it snaps to
    /// a shape, bake it, and then erase it. The shape has to land in the cel's own raster (not as a
    /// separate object tier) for the eraser to be able to punch through it at all.
    func testHeldStrokeBecomesAShapeThatTheEraserCanRemove() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))

        // A horizontal line across the middle of the canvas, held at the end so it snaps to a shape.
        drawAndHoldShape(on: canvas, from: CGVector(dx: 0.25, dy: 0.5), to: CGVector(dx: 0.75, dy: 0.5))
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)),
                       "The shape should be visible while it sits in the adjustable state")

        commitPendingShape(on: app)
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)),
                       "Baking the shape must leave the ink where the preview showed it")

        // Not just "still looks inked" — the pixels have to be in the cel's own raster, which is the
        // whole point of rasterizing on the way out of the transient state.
        app.buttons["toolbar.layersButton"].tap()
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 0), 1,
                       "The shape should have been stamped into the raster layer as one stroke")
        app.buttons["toolbar.layersButton"].tap()

        // Erase along the line. A shape stamped into the raster erases like any other stroke.
        // (The left rail's sliders are rotated and unreliable to `adjust` from XCUITest — see the
        // fill-slider tests — so this runs at the eraser's default size, which comfortably covers a
        // default-size brush stroke.)
        app.buttons["toolbar.eraserButton"].tap()
        drawLine(on: canvas, from: CGVector(dx: 0.25, dy: 0.5), to: CGVector(dx: 0.75, dy: 0.5))

        XCTAssertTrue(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)),
                      "The eraser should have removed the baked shape")
    }

    /// The vector-layer path: the same gesture must produce an ordinary `VectorStroke` — not a shape
    /// object, and not a raster stamp — so the vector eraser acts on it exactly as it acts on any
    /// freehand stroke drawn through the middle.
    ///
    /// What "acts on it" means has moved twice. Phase 4c stopped cutting partway at all (a cut piece
    /// re-phased its own dab lattice and landed ink outside what the punch covered), and Phase 4d
    /// brought the cut back once `DabLattice` let a piece render on its parent's dabs — so a gesture
    /// wide enough to cover the line's full width both cuts it *and* retains the punch.
    ///
    /// The counts are read per kind rather than as one total, and that is the part worth keeping: the
    /// original assertion here was `strokes == 2`, which one paint stroke plus one punch also
    /// satisfies, so it passed through the whole of Phase 4c while measuring nothing. Two paint pieces
    /// plus one punch is a different statement from one stroke plus one punch, and only the split
    /// counts say which happened.
    func testHeldStrokeOnVectorLayerBecomesAVectorStrokeTheEraserActsOn() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        app.buttons["toolbar.layersButton"].tap()
        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addButton.press(forDuration: 1.2) // long-press opens the kind menu
        let vectorItem = app.buttons["Vector Layer"]
        XCTAssertTrue(vectorItem.waitForExistence(timeout: 5))
        vectorItem.tap()
        app.buttons["toolbar.layersButton"].tap() // close the panel

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        drawAndHoldShape(on: canvas, from: CGVector(dx: 0.25, dy: 0.5), to: CGVector(dx: 0.75, dy: 0.5))
        commitPendingShape(on: app)

        app.buttons["toolbar.layersButton"].tap()
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.strokes, 1,
                       "The shape should commit as exactly one ordinary vector stroke")
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 1), 0,
                       "A shape on a vector layer must not be stamped into the raster tier")
        app.buttons["toolbar.layersButton"].tap()

        // Erase straight down through the middle of the shape, in the default mode (Mode 1).
        app.buttons["toolbar.eraserButton"].tap()
        drawLine(on: canvas, from: CGVector(dx: 0.5, dy: 0.42), to: CGVector(dx: 0.5, dy: 0.58))

        app.buttons["toolbar.layersButton"].tap()
        let after = readVectorMarker(app, layerIndex: 1)
        XCTAssertEqual(after?.strokes, 2,
                       "A gesture covering the shape's line full-width cuts it into two paint pieces "
                       + "— reading 1 means the split never fired")
        XCTAssertEqual(after?.erases, 1,
                       "Erasing across a shape should retain the gesture as one .erase punch, "
                       + "exactly as it does for a freehand stroke — the cut is inset inside the "
                       + "punch's footprint, so the punch is still what makes the edge")
    }

    /// The reported bug in its exact user-visible form: make a shape, then tap the eraser — and the
    /// shape vanishes until you erase something, at which point it comes back.
    ///
    /// Switching tools bakes the pending shape, which stamps the cel's `RasterLayerTexture` in
    /// place. That changes neither the `@Published layers` value nor the stroke view's own render,
    /// so the canvas kept showing its pre-bake picture: the ink was committed correctly and simply
    /// never repainted, and the next unrelated edit's own `refreshDisplay()` was what revealed it.
    /// Nothing is erased here on purpose — the whole assertion is that the ink is on screen the
    /// moment the tool changes. (`waitUntilFilled` just polls for "no longer blank paper", which is
    /// what makes this robust against when SwiftUI happens to run its pass.)
    func testShapeStaysOnScreenWhenSwitchingToTheEraser() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))

        drawAndHoldShape(on: canvas, from: CGVector(dx: 0.25, dy: 0.5), to: CGVector(dx: 0.75, dy: 0.5))
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)),
                       "The shape should be visible while it sits in the adjustable state")

        app.buttons["toolbar.eraserButton"].tap()

        XCTAssertTrue(waitUntilFilled(canvas, dx: 0.5, dy: 0.5, timeout: 5),
                      "Selecting the eraser bakes the pending shape — its ink must stay on screen, "
                      + "not disappear until some later edit happens to repaint the layer")
    }

    /// The undo/redo half of the same repaint gap. Undo and redo swap a baked shape's pixels back
    /// into the cel's raster in place, with no live stroke driving a redraw — so without the
    /// version check an undone shape stayed on screen and a redone one stayed missing.
    func testUndoAndRedoOfABakedShapeRepaintTheCanvas() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))

        drawAndHoldShape(on: canvas, from: CGVector(dx: 0.25, dy: 0.5), to: CGVector(dx: 0.75, dy: 0.5))
        commitPendingShape(on: app)
        XCTAssertTrue(waitUntilFilled(canvas, dx: 0.5, dy: 0.5, timeout: 5),
                      "The baked shape should be on screen before undoing it")

        app.buttons["sideToolbar.undoButton"].tap()
        XCTAssertTrue(waitUntilBlank(canvas, dx: 0.5, dy: 0.5, timeout: 5),
                      "Undoing the shape must repaint the layer, not leave the ink on screen")

        app.buttons["sideToolbar.redoButton"].tap()
        XCTAssertTrue(waitUntilFilled(canvas, dx: 0.5, dy: 0.5, timeout: 5),
                      "Redoing the shape must bring its ink back without waiting for another edit")
    }

    /// Drawing over a pending shape has to commit it *and* draw, in the one touch — the reported
    /// behaviour was that the first touch only dismissed the transient state, so the user had to
    /// lift and put the pen down a second time before any ink appeared.
    ///
    /// The shape overlay used to sit across the whole canvas with interaction enabled, swallowing
    /// that first touch as a "tap outside". It now only claims the touches that land on its handles,
    /// so this stroke reaches the stroke view, whose `onStrokeBegan` bakes the shape on the way past.
    func testDrawingOverAPendingShapeCommitsItAndDrawsInOneTouch() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))

        drawAndHoldShape(on: canvas, from: CGVector(dx: 0.25, dy: 0.38), to: CGVector(dx: 0.75, dy: 0.38))
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.38)),
                       "the shape should be sitting in the adjustable state")

        // One touch, well clear of the shape's endpoint handles.
        drawLine(on: canvas, from: CGVector(dx: 0.25, dy: 0.68), to: CGVector(dx: 0.75, dy: 0.68))

        XCTAssertTrue(waitUntilFilled(canvas, dx: 0.5, dy: 0.68, timeout: 5),
                      "the stroke drawn over a pending shape must land on the first touch, "
                      + "not be swallowed as a dismissal of the shape")
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.38)),
                       "committing the shape must keep its ink, not discard it")

        app.buttons["toolbar.layersButton"].tap()
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 0), 2,
                       "the layer should hold both the baked shape and the stroke drawn over it")
    }

    /// Grabbing a line's *start* handle has to move that end. Both handles reported through one
    /// callback that unconditionally wrote `endPoint`, so dragging the start handle silently
    /// dragged the far end instead and the line collapsed toward the handle being held.
    func testDraggingALinesStartHandleMovesThatEndAndLeavesTheOther() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))

        // A horizontal line; its start handle sits at dx 0.25, its end handle at dx 0.75.
        drawAndHoldShape(on: canvas, from: CGVector(dx: 0.25, dy: 0.5), to: CGVector(dx: 0.75, dy: 0.5))
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)),
                       "the line should be sitting in the adjustable state")

        // Drag the start handle down and to the right, far enough that the two possible outcomes
        // don't overlap anywhere:
        //   fixed  — the line runs (0.30, 0.75) → (0.75, 0.50), through (0.525, 0.625)
        //   broken — the *end* follows the finger instead, collapsing the line into the short
        //            stub (0.25, 0.50) → (0.30, 0.75), which never comes near that midpoint.
        let startHandle = canvas.coordinate(withNormalizedOffset: CGVector(dx: 0.25, dy: 0.5))
        startHandle.press(forDuration: 0.3,
                          thenDragTo: canvas.coordinate(withNormalizedOffset: CGVector(dx: 0.30, dy: 0.75)),
                          withVelocity: .slow,
                          thenHoldForDuration: 0.3)
        commitPendingShape(on: app)

        XCTAssertTrue(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)),
                      "the line should have moved off its original path")
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.525, dy: 0.625)),
                       "the line should run from the dragged start handle to the end that was left "
                       + "alone — an empty midpoint here means the far end followed the finger instead")
    }

    /// The vector-layer half of the "filled section gets duplicated in a very buggy way" report.
    ///
    /// A vector layer stores its content in *local* space and `VectorCanvas.render()` applies the
    /// layer transform on top. A fill path (taken from the flood mask) and a live stroke's samples
    /// are both captured in *canvas* space, and used to be stored verbatim — so on a layer that had
    /// been moved they went through the transform a second time and landed one displacement away
    /// from where they were put, reading as a detached second copy that slid further with every
    /// subsequent move. Driven here with a stroke rather than a fill because both go through the
    /// same mapping and a stroke needs no enclosing contour to be probed.
    func testContentDrawnOnAMovedVectorLayerLandsWhereItWasDrawn() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        app.buttons["toolbar.layersButton"].tap()
        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addButton.press(forDuration: 1.2) // long-press opens the kind menu
        let vectorItem = app.buttons["Vector Layer"]
        XCTAssertTrue(vectorItem.waitForExistence(timeout: 5))
        vectorItem.tap()
        app.buttons["toolbar.layersButton"].tap() // close the panel

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))

        // Something to move: a cross in the upper-left, well away from where the second stroke goes
        // so the two can never be mistaken for each other. Deliberately a cross rather than a single
        // line — Move boxes the layer's own *content bounds*, and one horizontal stroke's bounds are
        // a strip barely a brush-width tall, which a drag aimed at its centre can miss outright.
        drawLine(on: canvas, from: CGVector(dx: 0.25, dy: 0.28), to: CGVector(dx: 0.39, dy: 0.28))
        drawLine(on: canvas, from: CGVector(dx: 0.32, dy: 0.21), to: CGVector(dx: 0.32, dy: 0.35))
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.32, dy: 0.28)),
                       "The cross should be on screen before moving it")

        // Move the layer straight down. Move on a vector layer transforms the geometry via the
        // on-canvas box (no raster piece), and that box wraps the content bounds — so a drag from
        // the middle of the cross lands on the box body, which is what pans it.
        app.buttons["toolbar.moveButton"].tap()
        canvas.coordinate(withNormalizedOffset: CGVector(dx: 0.32, dy: 0.28))
            .press(forDuration: 0.5,
                   thenDragTo: canvas.coordinate(withNormalizedOffset: CGVector(dx: 0.32, dy: 0.48)),
                   withVelocity: .slow, thenHoldForDuration: 0.5)
        app.buttons["toolbar.moveButton"].tap() // leave Move

        // Guard against a vacuous pass: if the drag missed the box the layer never moved, and the
        // rest of this test would prove nothing.
        XCTAssertTrue(waitUntilFilled(canvas, dx: 0.32, dy: 0.48, timeout: 5),
                      "The Move drag should have carried the cross down to the new position")
        XCTAssertTrue(waitUntilBlank(canvas, dx: 0.32, dy: 0.28, timeout: 5),
                      "...and left its original position blank")

        // The real assertion: a stroke drawn now must land under the finger. No tool tap needed —
        // leaving Move restores the pen that was already selected, and tapping the brush button
        // here would only toggle its settings panel open over the canvas.
        drawLine(on: canvas, from: CGVector(dx: 0.55, dy: 0.70), to: CGVector(dx: 0.80, dy: 0.70))

        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.675, dy: 0.70)),
                       "A stroke drawn on an already-moved vector layer must land where it was "
                       + "drawn, not be put through the layer transform a second time")
    }

}
